<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetContentHtmlVO;

trait TemplateSnippetContentHtmlAccessor
{
    private TemplateSnippetContentHtmlVO $_contentHtml;
    public function getContentHtml(): string
    {
        return $this->_contentHtml->value();
    }
    public function contentHtml(): TemplateSnippetContentHtmlVO
    {
        return $this->_contentHtml;
    }
    public function isContentHtmlChanged(?self $original = null): bool
    {
        return !$this->_contentHtml->equals($original?->_contentHtml);
    }
    public function withContentHtml(TemplateSnippetContentHtmlVO|string $contentHtml): self
    {
        $copy = clone $this;
        $copy->_contentHtml = TemplateSnippetContentHtmlVO::from($contentHtml);
        return $copy;
    }
}
